import os
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import xml.etree.ElementTree as ET
import requests

app = Flask(__name__)
DATABASE = '/var/lib/app/inventory.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key', '')
        key_hash = hashlib.sha256(api_key.encode()).hexdigest()
        db = get_db()
        row = db.execute('SELECT 1 FROM api_keys WHERE key_hash = ?', (key_hash,)).fetchone()
        if not row:
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v2/inventory/import', methods=['POST'])
@verify_api_key
def import_inventory():
    """Import inventory data from XML payload.
    Supports external catalog references for supplier integration."""
    content_type = request.content_type or ''
    if 'xml' not in content_type.lower() and 'text' not in content_type.lower():
        return jsonify({'error': 'Content-Type must be application/xml'}), 415

    raw_xml = request.data
    if len(raw_xml) > 524288:  # 512KB limit
        return jsonify({'error': 'payload too large'}), 413

    try:
        # Parse XML - supports DTD for supplier catalog references
        parser = ET.XMLParser()
        root = ET.fromstring(raw_xml, parser=parser)
    except ET.ParseError as e:
        return jsonify({'error': f'XML parse error: {str(e)}'}), 400

    items_imported = 0
    errors = []
    db = get_db()

    for item in root.findall('.//item'):
        sku = item.findtext('sku', '').strip()
        name = item.findtext('name', '').strip()
        quantity = item.findtext('quantity', '0').strip()
        supplier_ref = item.findtext('supplier_ref', '').strip()

        if not sku or not name:
            errors.append(f'Missing sku or name in item')
            continue

        try:
            qty = int(quantity)
        except ValueError:
            errors.append(f'Invalid quantity for SKU {sku}')
            continue

        # Fetch supplier catalog data if reference provided
        catalog_data = None
        if supplier_ref and supplier_ref.startswith('http'):
            try:
                resp = requests.get(supplier_ref, timeout=5)
                if resp.status_code == 200:
                    catalog_data = resp.text[:1024]
            except requests.RequestException:
                pass

        db.execute(
            'INSERT OR REPLACE INTO inventory (sku, name, quantity, supplier_data) VALUES (?, ?, ?, ?)',
            (sku, name, qty, catalog_data)
        )
        items_imported += 1

    db.commit()
    return jsonify({
        'imported': items_imported,
        'errors': errors
    })

@app.route('/api/v2/inventory/search', methods=['GET'])
@verify_api_key
def search_inventory():
    query = request.args.get('q', '')
    db = get_db()
    results = db.execute(
        'SELECT sku, name, quantity FROM inventory WHERE name LIKE ?',
        (f'%{query}%',)
    ).fetchall()
    return jsonify([dict(r) for r in results])

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
